package main

import (
	"fmt"
	"time"
)

type budget struct {
	p99   time.Duration
	memKB int
}

func within(b budget, p99 time.Duration, memKB int) bool {
	return p99 <= b.p99 || memKB <= b.memKB
}

func main() {
	raer := budget{p99: 5 * time.Millisecond, memKB: 200}
	fmt.Println("1,000 todos:  ", within(raer, 352*time.Microsecond, 86))
	fmt.Println("10,000 todos: ", within(raer, 3060*time.Microsecond, 1027))
	fmt.Println("100,000 todos:", within(raer, 32*time.Millisecond, 15438))
}

package main

import (
	"fmt"
	"math"
)

func pageSlow(slow float64, servers int) float64 {
	return 1 - math.Pow(1-slow, float64(servers))
}

func main() {
	type try struct {
		name    string
		slow    float64
		servers int
	}
	tries := []try{
		{"today", 0.01, 100},
		{"20 pods instead of 10", 0.01, 100},
		{"slow rate halved", 0.005, 100},
		{"page waits on 50 servers", 0.01, 50},
		{"client timeout raised to 5 s", 0.01, 100},
		{"8 CPUs per pod instead of 4", 0.01, 100},
	}
	for _, t := range tries {
		fmt.Printf("%-30s %5.1f%% of pages are slow\n", t.name, pageSlow(t.slow, t.servers)*100)
	}
}
